begin;
do $$ declare v uuid; t timestamptz:=now(); begin
select id into strict v from books where lower(title)=lower('The Gruffalo');
delete from writing_trait_annotations where book_id=v; delete from reading_strategy_annotations where book_id=v; delete from pride_value_annotations where book_id=v; delete from inquiry_lens_annotations where book_id=v; delete from teaching_ideas where book_id=v; delete from why_use_bullets where book_id=v;
insert into writing_trait_annotations(book_id,trait_slug,year_level,in_this_book_text,applicable_year_levels,source_type,source_name,confidence,status,reviewed_by,reviewed_at,key_understanding_text,key_skill_text,display_order) select v,slug,yr,txt,yr,'ai_suggested','Ngarri curriculum and complete-text review','high','teacher_reviewed','Phill',t,ku,ks,ord from jsonb_to_recordset($json$[{"slug":"organisation","yr":"Foundation","ku":"writing is sequenced","ks":"I can include a beginning, middle and end (recount, narrative etc).","txt":"The beginning sends the mouse into the wood and establishes the danger posed by Fox, Owl and Snake. In the middle, the invented gruffalo becomes real and threatens him. The ending follows the mouse's plan back past the three animals until the Gruffalo flees and the mouse eats safely. Students can identify how each section changes the mouse's problem, then plan a simple narrative with a clear beginning, complication and resolution.","ord":1},{"slug":"organisation","yr":"Year 1","ku":"writing has organisational features and these features assist the reader to understand the message","ks":"I can explain the purpose of organisational features.","txt":"Each first encounter follows a recognisable pattern: invitation, polite refusal, a new Gruffalo feature, a frightening favourite food and the predator's departure. The refrain about the \"deep dark wood\" signals movement to the next episode. Students can explain how repetition helps the audience anticipate what belongs in each encounter and notice the important changes.","ord":2},{"slug":"organisation","yr":"Year 2","ku":"how different types of texts are organised differently","ks":"I can identify the structure of different text types.","txt":"Donaldson builds a trickster narrative in two linked halves. The mouse invents the Gruffalo while moving from Fox to Owl to Snake, then uses the real Gruffalo while returning from Snake to Owl to Fox. Students can map the forward and reverse journeys and explain how this mirrored structure turns the mouse's earlier invention into the solution.","ord":3},{"slug":"organisation","yr":"Year 3","ku":"writer's can varying pacing in their writing e.g to 'stretch out' a moment in my writing (spotlight) and when to speed through a moment.","ks":"I can include spotlights and speed throughs in my text to highlight key ideas and pace.","txt":"The repeated encounters move briskly because readers know the pattern, but the Snake episode stops mid-word before the Gruffalo is revealed feature by feature. Short exclamations then spotlight the shock. Students can compare this slowed reveal with the faster return encounters and try stretching one turning point while compressing repeated action in their own narrative.","ord":4},{"slug":"organisation","yr":"Year 5","ku":"there are a range of devices used to create cohesion in a text","ks":"I can use a range of devices to create cohesion within a text. (synonyms, cause and effect, conditionals).","txt":"Cohesion comes from recurring lines, parallel invitations, linked rhymes, cumulative Gruffalo features and the reversed sequence of Snake, Owl and Fox. Earlier details become causes in the ending: the mouse's invented creature frightens the predators, their flight misleads the Gruffalo, and \"favourite food\" becomes the final threat. Students can trace how repetition and cause-and-effect make the circular plot feel tightly connected rather than merely repetitive.","ord":5},{"slug":"word_choice","yr":"Foundation","ku":"writers select words to make their sentences more interesting","ks":"I can experiment with adjectives in my writing","txt":"The Gruffalo is created through memorable adjective-noun groups: terrible tusks and claws, knobbly knees, turned-out toes, orange eyes, a black tongue and purple prickles. Scheffler's illustrations confirm each detail. Students can notice how selected adjectives make an invented creature precise enough to picture, then choose a small set of details for a creature of their own.","ord":6},{"slug":"word_choice","yr":"Year 1","ku":"word choices enhance the reader's experience","ks":"I can use adjectives to describe the qualities of a noun.","txt":"Donaldson does not describe the Gruffalo all at once during the mouse's invention. Each predator hears a different pair of features, so the description grows while suspense builds. Students can sort the descriptive words by body part, explain what each adds to the audience's mental image, and revise a flat noun group into one vivid enough to illustrate.","ord":7},{"slug":"word_choice","yr":"Year 2","ku":"rhymes, rhythm and word patterns can be used to enhance the reader's experience","ks":"I can identify and use memorable words and phrases.","txt":"Couplet rhymes such as wood/good, mouse/house and rocks/fox make the text inviting to join in, while recurring patterns let readers anticipate lines without making every episode identical. The invented foods create playful rhyme and humour. Students can identify where the rhyme carries meaning as well as sound, then innovate one encounter whose place, creature and food form a coherent pattern.","ord":8},{"slug":"word_choice","yr":"Year 3","ku":"word choices are selected and refined, allowing the writer to communicate a message clearly","ks":"I can choose specific words and phrases for a desired effect.","txt":"The reactions escalate from the Gruffalo's \"Amazing!\" to \"Astounding!\", while the mouse transforms the other characters' food language into \"gruffalo crumble\" and prompts immediate flight. Students can examine how precise reaction words and the repeated \"favourite food\" phrase show the Gruffalo's growing belief, then select vocabulary that deliberately increases tension or confidence across a scene.","ord":9},{"slug":"voice_audience","yr":"Year 2","ku":"writing can capture a general mood and evoke emotions such as joy, fear, excitement and humour.","ks":"I can explain and justify ways I can engage my audience (e.g interesting leads, word choice, onomatopoeia, persuasive devices etc).","txt":"The narrator moves between playful rhyme, danger and comic relief. Each predator's invitation sounds courteous while the repeated statement that the mouse \"looked good\" reveals the threat; the interrupted denial and the exclamations at the Gruffalo's appearance create a sudden fright. Students can explain how rhyme, dramatic irony and abrupt exclamations let a young audience feel suspense without losing the story's humour.","ord":10},{"slug":"sentence_fluency","yr":"Year 1","ku":"my sentences need to sound smooth and fluent when I read them aloud.","ks":"I can re-read my sentences to check they sound smooth, fluent and maintain correct tense.","txt":"The couplets are designed for oral reading, with repeated sentence frames and natural pauses in the dialogue. Lines such as the mouse's movement through the wood return with small changes that preserve rhythm. Students can choral-read an encounter, mark where the voice naturally pauses, and revise an awkward patterned sentence until it fits the established beat and can be read smoothly.","ord":11},{"slug":"sentence_fluency","yr":"Year 2","ku":"varying the start, structure and length of sentences enhances the reader's experience","ks":"I can experiment with different length sentences for effect.","txt":"Longer rhyming sentences carry invitations, descriptions and walking, while compact questions and exclamations interrupt them: \"What's a gruffalo?\", \"Oh crumbs!\" and \"Oh help! Oh no!\" The contrast quickens reactions and spotlights surprise. Students can compare the effect of the long and short lines, then vary sentence length at a moment of discovery or danger in their own writing.","ord":12},{"slug":"presentation","yr":"Year 1","ku":"visuals can enhance my writing","ks":"I can select/create visuals that will enhance the reader's understanding.","txt":"Before the full Gruffalo appears, Scheffler's pictures make the mouse's separate descriptions visible, including a circular close-up of orange eyes, black tongue and purple prickles. When the creature finally arrives, the illustration gathers all the earlier details into one body. Students can explain how the images help readers retain cumulative information, then plan illustrations that reveal selected details before showing a complete character.","ord":13}]$json$::jsonb) x(slug text,yr text,ku text,ks text,txt text,ord int);
insert into reading_strategy_annotations(book_id,strategy_slug,year_level,in_this_book_text,applicable_year_levels,source_type,source_name,confidence,status,reviewed_by,reviewed_at,key_understanding_text,key_skill_text,display_order) select v,slug,yr,txt,yr,'ai_suggested','Ngarri curriculum and complete-text review','high','teacher_reviewed','Phill',t,ku,ks,ord from jsonb_to_recordset($json$[{"slug":"predicting","yr":"Foundation","ku":"Predicting is when we think about what might happen in the book.","ks":"I can predict the problem and solution of the text using what has already happened in the text.","txt":"After Fox and Owl both invite the mouse home and are frightened by invented foods, students have a strong pattern for predicting what Snake wants and how the mouse may respond. They can name the repeated clues, make a plausible prediction, and check which parts repeat and which details Donaldson changes.","ord":1},{"slug":"predicting","yr":"Year 1","ku":"Predicting is when we make an educated guess about what might happen within the text. (predicting)","ks":"I can change my predictions as I gain more information when reading. (predicting)","txt":"The mouse repeatedly insists that no Gruffalo exists, so readers may predict another successful escape after Snake. The interrupted word and the assembled description require that prediction to change when the real creature appears. Students can preserve their original evidence, identify the new clue that overturns it, and form a new prediction about how the mouse might escape.","ord":2},{"slug":"predicting","yr":"Year 2","ku":"Using our prior knowledge and text evidence helps us more accurate predictions.","ks":"I can use my prior knowledge and text evidence to make, confirm or modify predictions.","txt":"Once the mouse asks the Gruffalo to walk behind him, readers can combine knowledge of the earlier frightened animals with the mouse's claim that everyone fears him. Students can predict that the predators will see the Gruffalo rather than the mouse as the danger, then refine the prediction as Snake, Owl and Fox flee in reverse order.","ord":3},{"slug":"inferring","yr":"Foundation","ku":"Clues within a text are needed to infer the emotions of a character","ks":"I can infer the emotions of a character using pictures and words (happy, sad, angry, excited, tired).","txt":"When the real Gruffalo appears, the narrator exclaims and Scheffler shows the mouse dwarfed beneath him; the mouse then answers with a bold claim rather than an explicit statement of fear. Students can combine words, scale, posture and the immediate danger to infer how the mouse may feel while distinguishing his inner feeling from the confidence he performs.","ord":4},{"slug":"inferring","yr":"Year 1","ku":"Inferring is when we work out what the author doesn't exactly say.","ks":"I can infer character feelings using text clues such as pictures and words.","txt":"The predators never announce that they planned to eat the mouse. Their invitations are polite, but the narrator repeats that the mouse \"looked good\", and each proposes a private home. Students can infer the hidden intention by combining that wording with the pictures and explain why the mouse invents a frightening lunch companion instead of accepting.","ord":5},{"slug":"inferring","yr":"Year 3","ku":"Using a range of text clues can help me make predictions and inferences.","ks":"I can infer a character's traits using different clues.","txt":"The mouse notices what each character fears and adapts his story immediately: a place nearby, a Gruffalo feature and a favourite food tailored to the listener. When the invention becomes real, he repurposes the animals' fear into evidence of his own power. Students can infer resourcefulness, quick thinking and composure from this sequence rather than labelling him clever without evidence.","ord":6},{"slug":"synthesising","yr":"Year 2","ku":"That synthesis is when we use our prior knowledge and the text to build deeper understandings. (Synthesising)","ks":"I can identify how the new knowledge developed my thinking. (synthesising)","txt":"At first, size seems to determine power: each predator threatens the mouse, and the Gruffalo is larger than all of them. Across the return journey, readers integrate a new idea: what characters believe about power can shape their actions as strongly as physical size. Students can record how their view of the mouse changes after the first trick, the real Gruffalo's arrival and the reversed encounters.","ord":7},{"slug":"summarising","yr":"Foundation","ku":"Retelling is when I tell what happened in the text","ks":"I can retell the beginning, problem and solution of a text.","txt":"The repeated episodes can tempt a retell into reciting every rhyme. Students can select the mouse's dangerous journey as the beginning, the arrival of the real Gruffalo as the central problem, and the reverse walk plus \"gruffalo crumble\" as the solution. The final nut confirms that the mouse is safe.","ord":8},{"slug":"summarising","yr":"Year 2","ku":"Summarising is when we retell the most important information from within a text.","ks":"I can summarise a text in the correct sequence.","txt":"A concise summary must preserve both journeys because the second depends on the first, but it need not repeat every body part, invitation or rhyme. Students can group Fox, Owl and Snake as a repeated pattern, retain the turning point where the imaginary Gruffalo becomes real, and explain how the reversed encounters cause the resolution.","ord":9},{"slug":"analysing","yr":"Year 2","ku":"Texts use different language features depending on their purpose.","ks":"I can make connections between language features and their purpose.","txt":"Donaldson entertains through rhyming couplets, patterned dialogue, cumulative description, repeated refrains and a surprise reversal. Students can match each feature to a purpose: rhyme supports oral participation, repetition establishes expectations, cumulative details prepare the reveal, and the reverse sequence makes the mouse's final deception convincing.","ord":10}]$json$::jsonb) x(slug text,yr text,ku text,ks text,txt text,ord int);
insert into pride_value_annotations(book_id,value_slug,in_this_book_text,confidence,status,reviewed_by,reviewed_at,display_order) select v,slug,txt,'high','teacher_reviewed','Phill',t,ord from jsonb_to_recordset($json$[{"slug":"determination","txt":"The mouse meets four escalating threats and repeatedly finds a new way forward. His first strategy is to invent the Gruffalo for each predator; when that invention unexpectedly becomes real, he does not freeze or simply repeat the same claim. He designs a new test, leads the Gruffalo past the other animals and turns their fear into protection. This is a strong example of adapting a strategy when circumstances change, while leaving room to discuss whether every effective strategy is also fair.","ord":1},{"slug":"integrity","txt":"The mouse protects himself through deliberate deception, first inventing the Gruffalo and later claiming that the animals fear him. The lies prevent him from being eaten, but they are not examples of honesty. The book creates a useful ethical dilemma: students can distinguish understanding why a vulnerable character lies from calling the lie an act of integrity, and consider what fairness or responsibility might mean when every larger character intends harm.","ord":2}]$json$::jsonb) x(slug text,txt text,ord int);
insert into inquiry_lens_annotations(book_id,lens_slug,in_this_book_text,confidence,status,reviewed_by,reviewed_at,display_order) select v,slug,txt,'high','teacher_reviewed','Phill',t,ord from jsonb_to_recordset($json$[{"slug":"identity_creativity_wellbeing","txt":"The mouse's physical size stays the same, but his social position changes as he uses imagination, language and an understanding of others' viewpoints. The Gruffalo first sees food, then begins to see a frightening leader. Students can inquire into the relationship between how capable we are, how others perceive us and the wise choices we make under pressure. The story also opens a productive tension between creative self-protection and the consequences of misleading others.","ord":1}]$json$::jsonb) x(slug text,txt text,ord int);
insert into teaching_ideas(book_id,title,description,time_minutes,"grouping",difficulty,colour_tag,is_generic,status,year_levels,linked_focus,where_to_look,learning_focus,teaching_sequence,student_application,notice_learning,display_order,reviewed_by,reviewed_at) select v,title,learning,minutes,grouping,difficulty,'green',false,'teacher_reviewed',years,focus,look,learning,sequence,application,notice,ord,'Phill',t from jsonb_to_recordset($json$[{"title":"Predict the third encounter from the pattern","focus":"Predicting; Organisation","years":"Foundation-1","minutes":20,"grouping":"Whole class","difficulty":"Entry","look":"Pause after Owl flies away and before Snake invites the mouse to his logpile house.","learning":"Use repeated structural clues to make a specific, revisable prediction.","sequence":"Revisit the Fox and Owl encounters; jointly identify the recurring invitation, refusal, Gruffalo description, favourite food and escape; model a prediction that names two pattern clues; reveal the Snake encounter in stages and revise details that differ.","application":"Partners create an oral fourth encounter that preserves the structure while changing the creature, location, Gruffalo feature and food.","notice":"Students justify predictions with repeated evidence and understand that a pattern supports, but does not guarantee, exact outcomes.","ord":1},{"title":"Build and reveal a creature","focus":"Word Choice; Presentation","years":"Foundation-2","minutes":35,"grouping":"Individual","difficulty":"Medium","look":"The Gruffalo features distributed across the three first encounters, the circular close-up and the full reveal.","learning":"Select precise adjective-noun groups and sequence visual information to build a coherent image.","sequence":"Collect each printed feature without showing the complete Gruffalo; group words by body part; compare students' mental images with Scheffler's assembled creature; discuss why a few precise details are more useful than many unrelated adjectives.","application":"Students plan an invented creature in three partial reveals and one final illustration, writing one memorable detail for each stage.","notice":"Details belong to one coherent creature, adjectives add specific meaning, and the final visual matches the accumulated description.","ord":2},{"title":"Hear what makes the rhyme work","focus":"Word Choice; Sentence Fluency","years":"1-3","minutes":25,"grouping":"Pairs","difficulty":"Medium","look":"One complete predator encounter and the invented food rhyme at its end.","learning":"Use rhyme, stress and sentence sense together rather than choosing a rhyme alone.","sequence":"Choral-read the passage; mark end rhymes and clap the strong beats; replace one rhyming word with a sound match that breaks meaning and diagnose the problem; jointly compose a place/food pair that makes narrative sense and can be read fluently.","application":"Students draft and rehearse a four-line encounter, revising until the rhyme supports both meaning and oral flow.","notice":"Lines make grammatical and narrative sense, the rhyme is not forced, and students revise by listening aloud.","ord":3},{"title":"Revise a prediction at the interrupted word","focus":"Predicting; Audience/Voice; Organisation","years":"1-3","minutes":20,"grouping":"Whole class","difficulty":"Entry","look":"The mouse's interrupted claim after Snake leaves, followed by the feature-by-feature Gruffalo reveal.","learning":"Recognise how an author disrupts a pattern and revise an interpretation when new evidence appears.","sequence":"Stop at the unfinished word; think aloud that the familiar refrain suggests one outcome but the interruption signals a change; gather two plausible predictions; reveal the creature one feature at a time; name exactly which evidence confirms or overturns each prediction.","application":"Students add an interruption and slowed reveal to a short patterned scene of their own.","notice":"Students retain earlier evidence, identify the decisive new clue and explain why a revision is stronger than the first guess.","ord":4},{"title":"Infer the plan behind the brave voice","focus":"Inferring; Identity, Creativity and Wellbeing","years":"1-3","minutes":30,"grouping":"Pairs","difficulty":"Medium","look":"The real Gruffalo's threat, the mouse's claim to be the scariest creature, and the Gruffalo following behind.","learning":"Infer feelings, traits and strategy from the difference between what a character may feel and what the character chooses to say.","sequence":"Separate explicit evidence from inference; model how the Gruffalo's size and threat suggest danger while the mouse's words project confidence; track what the mouse needs the Gruffalo to see at each return encounter; test alternative trait labels against the whole sequence.","application":"Students write a brief internal thought and spoken line for a character concealing fear, then explain the evidence behind each.","notice":"Students distinguish feeling from performance and support a trait inference with several connected clues.","ord":5},{"title":"Map the story forward and backward","focus":"Organisation; Summarising; Analysing","years":"2-5","minutes":40,"grouping":"Small group","difficulty":"Medium","look":"Fox-Owl-Snake on the outward journey; Snake-Owl-Fox on the return.","learning":"Explain how mirrored structure creates cohesion and turns earlier details into causes in the resolution.","sequence":"Place the six encounters on a path; connect each first encounter to its return; annotate what repeats, what reverses and what gains a new meaning; remove one encounter and test how the mouse's claim becomes less convincing; jointly write a concise structural explanation.","application":"Students plan a short journey narrative in which three early details return in reverse order to solve the central problem.","notice":"Students explain function and cause, not only sequence, and use recurring details purposefully in their own plan.","ord":6},{"title":"Is a clever lie an act of integrity?","focus":"Integrity; Determination; Identity, Creativity and Wellbeing","years":"3-6","minutes":35,"grouping":"Whole class","difficulty":"Medium","look":"The predators' invitations, the invented Gruffalo, the real Gruffalo's threat and the mouse's final claim about Gruffalo crumble.","learning":"Reason about honesty, fairness, safety and responsibility without reducing an ethical dilemma to a character label.","sequence":"Establish the intentions and relative power of each character from evidence; sort the mouse's claims into true, invented and strategically misleading; use the exact Ngarri Integrity wording to test rather than assume the value; consider whether danger changes responsibility and what non-deceptive options were realistically available.","application":"Students write a reasoned response beginning, \"The mouse's choice is understandable because..., but it is/is not an example of integrity because...\" and address one counterargument.","notice":"Students distinguish explanation from endorsement, use the value wording accurately and support a nuanced judgement with events from the book.","ord":7}]$json$::jsonb) x(title text,focus text,years text,minutes int,grouping text,difficulty text,look text,learning text,sequence text,application text,notice text,ord int);
insert into why_use_bullets(book_id,text,display_order,status) select v,txt,ord,'teacher_reviewed' from jsonb_to_recordset($json$[{"txt":"Exceptional mentor text for patterned and mirrored narrative organisation","ord":1},{"txt":"Models memorable rhyme, cumulative description and fluent oral language","ord":2},{"txt":"High-yield predicting and inferring at carefully designed turning points","ord":3},{"txt":"Makes a small character's strategic thinking visible through dialogue and structure","ord":4},{"txt":"Opens nuanced discussion of determination, integrity, power and wise choices","ord":5}]$json$::jsonb) x(txt text,ord int);
update books set illustrator='Scheffler, Axel',text_type='Narrative',genre='Rhyming cumulative tale; trickster tale; circular quest narrative',year_level_min=0,year_level_max=6,updated_at=t where id=v;
end $$; commit;